import React, { useEffect, useRef, useState } from 'react';
import { portfolioData } from '../data/mock';

const AboutSection = () => {
    const [isVisible, setIsVisible] = useState(false);
    const sectionRef = useRef(null);

    useEffect(() => {
        const currentRef = sectionRef.current;
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setIsVisible(true);
                }
            },
            {
                threshold: 0.3
            }
        );

        if (currentRef) {
            observer.observe(currentRef);
        }

        return () => {
            if (currentRef) {
                observer.unobserve(currentRef);
            }
        };
    }, []);

    return (
        <section
            ref={sectionRef}
            className="min-h-screen bg-gradient-to-br from-slate-900 via-gray-900 to-slate-900 py-20 overflow-hidden relative"
        >
            <div className="container mx-auto px-6 relative z-10">
                <div className="grid lg:grid-cols-2 gap-16 items-center">
                    <div className="space-y-8">
                        <h2 className="text-5xl font-bold text-white">
                            About <span className="bg-gradient-to-r from-cyan-400 to-blue-500 bg-clip-text text-transparent">Me</span>
                        </h2>
                        <div className="space-y-4 text-gray-300 text-lg leading-relaxed">
                            <p>
                                With years of experience in full-stack development, I specialize in building scalable,
                                high-performance applications that deliver exceptional user experiences. My approach
                                combines technical excellence with creative problem-solving.
                            </p>
                            <p>
                                I'm always eager to take on new challenges and learn cutting-edge technologies.
                                Let's build something amazing together!
                            </p>
                        </div>
                    </div>

                    {/* Video placeholder - Replace with your Lego minifigure space video */}
                    <div className="relative h-[600px] bg-gray-950/50 backdrop-blur-sm rounded-lg border border-cyan-500/30 overflow-hidden shadow-2xl shadow-cyan-500/10 flex items-center justify-center">
                        <video
                            autoPlay
                            loop
                            muted
                            playsInline
                            className="w-full h-full object-cover"
                            poster="/path-to-your-video-thumbnail.jpg"
                        >
                            <source src="/videos/lego-space.mp4" type="video/mp4" />
                            <source src="/videos/lego-space.webm" type="video/webm" />
                        </video>

                        {/* Fallback placeholder when video is not available */}
                        <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-900/90 backdrop-blur-sm">
                            <div className="text-center space-y-4 p-8">
                                <div className="w-20 h-20 mx-auto bg-gradient-to-br from-cyan-500 to-blue-500 rounded-full flex items-center justify-center animate-pulse">
                                    <svg className="w-10 h-10 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" />
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                                    </svg>
                                </div>
                                <h3 className="text-xl font-bold text-cyan-400">Video Placeholder</h3>
                                <p className="text-gray-400 text-sm max-w-xs">
                                    Replace the video source in AboutSection.jsx with your Lego minifigure space animation
                                </p>
                                <div className="text-xs text-gray-500 font-mono mt-4 bg-gray-800 p-3 rounded">
                                    /videos/lego-space.mp4
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            {/* Background glow */}
            <div className="absolute top-1/2 right-0 w-96 h-96 bg-cyan-500/10 rounded-full blur-3xl"></div>
        </section>
    );
};

export default AboutSection;
